<template>
  <main class="container page-section ai-page">
    <header class="ai-page__header"><div><p class="eyebrow">Own-Web AI</p><h1 class="page-title">站内助手</h1><p>站内问题会显示已授权来源；普通聊天不会假装检索过资料。</p></div><button class="button button-primary" type="button" :disabled="ai.state.availability !== 'available'" @click="newConversation"><AppIcon name="plus" :size="17" />新对话</button></header>
    <p v-if="ai.state.availability === 'disabled'" class="ai-page__notice" role="status">{{ ai.state.error || 'AI 功能暂未启用。' }}</p>
    <div v-else class="ai-page__grid">
      <aside class="ai-page__history card" aria-label="AI 会话历史"><div class="ai-page__history-head"><strong><AppIcon name="history" :size="17" />会话</strong><button class="ai-history-refresh" type="button" :disabled="ai.loadingHistory.value" aria-label="刷新会话" @click="ai.loadConversations"><AppIcon name="rotate-cw" :size="16" /></button></div><p v-if="!ai.loggedIn()" class="ai-page__guest-note">访客会话仅在当前浏览器会话中保留。</p><p v-else-if="ai.loadingHistory.value" class="ai-page__guest-note" role="status">正在读取历史…</p><div v-else-if="!ai.conversations.value.length" class="ai-page__guest-note">还没有历史对话。</div><div v-else class="ai-history-list"><div v-for="conversation in ai.conversations.value" :key="conversation.id" class="ai-history-item" :class="{ active: ai.state.conversationId === conversation.id }"><button type="button" @click="ai.openConversation(conversation.id)">{{ conversation.title || '新对话' }}</button><span><button class="ai-history-icon" type="button" :aria-label="`重命名 ${conversation.title}`" @click="startRename(conversation)"><AppIcon name="pen" :size="14" /></button><button class="ai-history-icon" type="button" :aria-label="`删除 ${conversation.title}`" @click="confirmDelete(conversation)"><AppIcon name="trash" :size="14" /></button></span></div></div></aside>
      <section class="ai-page__chat card"><div class="ai-page__chat-head"><div><strong>{{ activeTitle }}</strong><small v-if="ai.state.pageContext?.selectedText">已附加文章选文</small></div><label>模型<select v-model="ai.state.selectedModel" :disabled="ai.isStreaming.value"><option v-for="model in ai.state.models" :key="model.id" :value="model.id">{{ model.label }}</option></select></label></div><AiChatSurface /></section>
    </div>
    <div v-if="renameTarget" class="ai-confirm-backdrop" @click.self="renameTarget = null"><form class="ai-confirm card" role="dialog" aria-modal="true" aria-labelledby="ai-rename-title" @submit.prevent="submitRename"><h2 id="ai-rename-title">重命名会话</h2><label class="field"><span>标题</span><input ref="renameInput" v-model.trim="renameValue" maxlength="180" /></label><div><button class="button" type="button" @click="renameTarget = null">取消</button><button class="button button-primary" type="submit">保存</button></div></form></div>
    <div v-if="deleteTarget" class="ai-confirm-backdrop" @click.self="deleteTarget = null"><section class="ai-confirm card" role="dialog" aria-modal="true" aria-labelledby="ai-delete-title" @keydown.esc.prevent="deleteTarget = null"><h2 id="ai-delete-title">删除会话？</h2><p>将删除该会话及其消息，且无法恢复。</p><div><button class="button" type="button" @click="deleteTarget = null">取消</button><button class="button button-danger" type="button" @click="deleteConversation">删除</button></div></section></div>
  </main>
</template>

<script setup lang="ts">
import { computed, nextTick, onMounted, ref } from 'vue'
import AppIcon from '@/components/AppIcon.vue'
import AiChatSurface from '@/components/ai/AiChatSurface.vue'
import { useAi, type AiConversation } from '@/services/ai'

const ai = useAi()
const renameTarget = ref<AiConversation | null>(null)
const deleteTarget = ref<AiConversation | null>(null)
const renameValue = ref('')
const renameInput = ref<HTMLInputElement | null>(null)
const activeTitle = computed(() => ai.conversations.value.find((item) => item.id === ai.state.conversationId)?.title || '新对话')
onMounted(async () => { if (ai.state.availability === 'unknown') await ai.refreshAvailability(); await ai.loadConversations(); if (!ai.state.conversationId && ai.conversations.value[0]) await ai.openConversation(ai.conversations.value[0].id) })
async function newConversation() { await ai.createConversation() }
function startRename(conversation: AiConversation) { renameTarget.value = conversation; renameValue.value = conversation.title; nextTick(() => renameInput.value?.focus()) }
async function submitRename() { if (!renameTarget.value) return; if (await ai.renameConversation(renameTarget.value.id, renameValue.value)) renameTarget.value = null }
function confirmDelete(conversation: AiConversation) { deleteTarget.value = conversation }
async function deleteConversation() { if (!deleteTarget.value) return; await ai.removeConversation(deleteTarget.value.id); deleteTarget.value = null }
</script>

<style scoped>
.ai-page { max-width: 1180px; }.ai-page__header { display: flex; align-items: end; justify-content: space-between; gap: var(--space-4); }.ai-page__header h1 { margin-bottom: var(--space-2); }.ai-page__header p:last-child { max-width: 650px; margin: 0; color: var(--muted); }.ai-page__notice { margin-top: var(--space-5); padding: var(--space-4); border: 1px solid var(--border); border-radius: var(--radius); color: var(--muted); background: var(--surface); }.ai-page__grid { display: grid; grid-template-columns: 260px minmax(0, 1fr); gap: var(--space-4); margin-top: var(--space-6); }.ai-page__history { align-self: start; padding: var(--space-3); }.ai-page__history-head { display: flex; align-items: center; justify-content: space-between; gap: var(--space-2); padding-bottom: var(--space-2); border-bottom: 1px solid var(--border); }.ai-page__history-head strong { display: inline-flex; align-items: center; gap: var(--space-2); }.ai-history-refresh, .ai-history-icon { display: inline-grid; place-items: center; width: 30px; height: 30px; padding: 0; border: 0; border-radius: 6px; color: var(--muted); background: transparent; }.ai-history-refresh:hover, .ai-history-icon:hover { color: var(--accent); background: var(--accent-soft); }.ai-page__guest-note { margin: var(--space-3) 0 0; color: var(--muted); font-size: .84rem; }.ai-history-list { display: grid; gap: var(--space-1); margin-top: var(--space-3); }.ai-history-item { display: flex; align-items: center; gap: var(--space-1); border-radius: 6px; }.ai-history-item.active { background: var(--accent-soft); }.ai-history-item > button { min-width: 0; flex: 1; overflow: hidden; padding: 8px; border: 0; border-radius: 6px; background: transparent; color: var(--text); text-align: left; text-overflow: ellipsis; white-space: nowrap; }.ai-history-item > span { display: flex; }.ai-page__chat { min-height: min(680px, calc(100vh - 190px)); padding: var(--space-4); }.ai-page__chat-head { display: flex; align-items: center; justify-content: space-between; gap: var(--space-3); margin-bottom: var(--space-3); }.ai-page__chat-head > div { display: grid; gap: 2px; }.ai-page__chat-head small { color: var(--accent); }.ai-page__chat-head label { display: grid; gap: 3px; color: var(--muted); font-size: .76rem; }.ai-page__chat-head select { max-width: 220px; padding: 6px 8px; border: 1px solid var(--border); border-radius: 6px; background: var(--surface-raised); color: var(--text); }.ai-confirm-backdrop { position: fixed; z-index: 40; inset: 0; display: grid; place-items: center; padding: var(--space-4); background: var(--scrim); }.ai-confirm { display: grid; gap: var(--space-4); width: min(440px, 100%); padding: var(--space-5); }.ai-confirm h2, .ai-confirm p { margin: 0; }.ai-confirm > div { display: flex; justify-content: end; gap: var(--space-2); }.ai-confirm .field { margin: 0; } @media (max-width: 760px) { .ai-page__header { align-items: start; flex-direction: column; }.ai-page__grid { grid-template-columns: 1fr; }.ai-page__history { max-height: 240px; overflow: auto; }.ai-page__chat { min-height: calc(100vh - 220px); }.ai-page__chat-head { align-items: start; flex-direction: column; }.ai-page__chat-head label, .ai-page__chat-head select { width: 100%; max-width: none; } }
</style>
